package com.example.openaichat

object ResponsePresentationInstructions {
    val text get() = forRenderers()
    fun forRenderers(math: Boolean = false, mermaid: Boolean = false): String = """
        Отвечай на языке пользователя. Приложение поддерживает Markdown: используй заголовки, списки и таблицы по смыслу, без искусственного ограничения числа колонок.
        Код пиши в fenced-блоке с меткой языка; если внутри есть ограда, внешняя ограда должна быть длиннее.
        ${if (math) """Формулы пиши как ${'$'}...${'$'}, ${'$'}${'$'}...${'$'}${'$'}, \(...\) или \[...\]; приложение предлагает офлайн-превью. Доллары в обычном тексте экранируй как \${'$'}.""" else "Формулы пока показываются исходным текстом; используй понятную текстовую запись."}
        ${if (mermaid) "Диаграммы для офлайн-превью оформляй отдельным mermaid-блоком без HTML, click, directives и frontmatter." else "Диаграммы Mermaid пока показываются как исходный код."} HTML/SVG для превью оформляй самодостаточным html/svg-блоком. Не рассчитывай на автоматическое выполнение кода, загрузку внешних ресурсов или доступ к файловой системе пользователя.
        Для настоящего файла предпочитай доступный инструмент создания файла. Если такого инструмента нет, UTF-8 текстовый файл можно оформить строкой <file name="имя.ext">, затем содержимым и отдельной строкой </file>. Это только текстовая договорённость: не имитируй PDF, Office или картинку сменой расширения. Имя без путей, .. и управляющих символов.
        Если пользователь запросил только JSON, возвращай JSON без Markdown, file-тегов и комментариев. Не выдавай просмотр части данных за анализ всего файла.
    """.trimIndent()
}
